sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {

	//g_form.setVisible("assignment_group");

      return;
   }

    var currentassgrp=newValue;
	var oldassgrpvalue = oldValue;

   var ga = new GlideAjax("servicedeskandhelpdesk");
   ga.addParam("sysparm_name","deskchange");
   ga.addParam("first",currentassgrp);
   ga.addParam("second",oldassgrpvalue);
   ga.getXMLAnswer(getassig);

   function getassig(response){

		var ans = response ;
		if (ans == "true"){
			g_form.addInfoMessage("can save");


		}
		else{
			g_form.addErrorMessage("can't save");
			g_form.clearValue("assignment_group");
		}

   }

   //Type appropriate comment here, and begin script below

}
